  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ options: "[session(true)]" })
}).then(response => response.json());

try {
  const first = await postForm("/toplevel_call", {
    pid: spawned.pid,
    goal: "member(X,[a,b,c])",
    limit: "1",
    format: "json"
  });
  // Route first.type, then use next/poll/respond as required.
} finally {
  try {
    await postForm("/toplevel_halt", {
      pid: spawned.pid,
      format: "json"
    });
  } catch (_olderNode) {
    await postForm("/toplevel_abort", {
      pid: spawned.pid,
      format: "json"
    });
  }
}

